type JsonRecord = Record<string, unknown>;

function isRecord(value: unknown): value is JsonRecord {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function isRecordArray(value: unknown): value is Array<Record<string, unknown>> {
  return Array.isArray(value) && value.every(isRecord);
}

function nonEmpty(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : undefined;
}

function oneOf<T extends string>(values: readonly T[], value: unknown): value is T {
  return typeof value === 'string' && (values as readonly string[]).includes(value);
}

function parseJson(content: string, label: string, errors: string[]): JsonRecord | null {
  try {
    const parsed = JSON.parse(content) as unknown;
    if (isRecord(parsed)) return parsed;
    errors.push(`${label} must be a JSON object.`);
  } catch (error) {
    errors.push(`${label} is not valid JSON${error instanceof Error ? `: ${error.message}` : '.'}`);
  }
  return null;
}

/** `evidence.md#f1-scope` → `f1-scope`. */
function anchorOf(ref: string): string | null {
  const index = ref.indexOf('#');
  const anchor = index >= 0 ? ref.slice(index + 1).trim() : '';
  return anchor || null;
}

/** A Markdown heading's anchor, as GitHub and VS Code write it: `## F1: EAC mode` → `f1-eac-mode`. */
function headingSlug(heading: string): string {
  return heading.trim().toLowerCase().replace(/[^a-z0-9 _-]/g, '').replace(/ /g, '-');
}

/** An anchor is an `id="…"` in evidence.md, or a heading whose slug it is. */
function hasAnchor(evidence: string, anchor: string): boolean {
  if (evidence.includes(`id="${anchor}"`) || evidence.includes(`id='${anchor}'`)) return true;
  const wanted = anchor.toLowerCase();
  for (const match of evidence.matchAll(/^#{1,6}[ \t]+(.+?)[ \t#]*$/gm)) {
    if (headingSlug(match[1]) === wanted) return true;
  }
  return false;
}

const ORG_ID = /^00D[A-Za-z0-9]{12,15}$/;

function fileRef(value: string): string {
  return value
    .replace(/\\/g, '/')
    .split('/')
    .filter((segment) => segment && segment !== '.' && segment !== '..')
    .join('/');
}

