export function validateInsightPacketManifest(content: string): {
  manifest?: InsightPacketManifest;
  errors: string[];
  warnings: string[];
} {
  const errors: string[] = [];
  const warnings: string[] = [];
  const raw = parseJson(content, 'manifest.json', errors);
  if (!raw) return { errors, warnings };

  const version = raw.version;
  if (version !== 1 && version !== 2 && version !== 3) errors.push('manifest.version must be 1, 2 or 3.');
  if (raw.kind !== INSIGHT_PACKET_KIND) errors.push(`manifest.kind must be ${INSIGHT_PACKET_KIND}.`);

  const createdAt = nonEmpty(raw.createdAt);
  if (!createdAt || Number.isNaN(Date.parse(createdAt))) errors.push('manifest.createdAt must be an ISO-8601 timestamp.');

  const source = isRecord(raw.source) ? raw.source : null;
  if (!source) errors.push('manifest.source must be an object.');
  const workspaceName = source ? nonEmpty(source.workspaceName) : undefined;
  if (source && !workspaceName) errors.push('manifest.source.workspaceName must be a non-empty string.');
  const gitBranch = source ? nonEmpty(source.gitBranch) : undefined;
  if (source && !gitBranch) warnings.push('manifest.source.gitBranch is blank; the branch shows as unknown.');
  const gitCommit = source?.gitCommit;
  if (gitCommit !== undefined && gitCommit !== null && typeof gitCommit !== 'string') {
    errors.push('manifest.source.gitCommit must be a string or null.');
  }

  const agentSession = isRecord(raw.agentSession) ? raw.agentSession : null;
  if (!agentSession) errors.push('manifest.agentSession must be an object.');
  const agent = agentSession?.agent;
  if (agentSession && !oneOf(INSIGHT_AGENTS, agent)) errors.push('manifest.agentSession.agent must be codex, claude_code or other.');
  const toolsUsed = agentSession?.toolsUsed;
  if (agentSession && !isStringArray(toolsUsed)) errors.push('manifest.agentSession.toolsUsed must be an array of strings.');
  else if (agentSession && (toolsUsed as string[]).length === 0) warnings.push('manifest.agentSession.toolsUsed is empty.');

  const goals = raw.goals;
  if (!isStringArray(goals)) errors.push('manifest.goals must be an array of strings.');
  else if (goals.length === 0) warnings.push('manifest.goals is empty.');

  const files = isRecord(raw.files) ? raw.files : null;
  if (!files) errors.push('manifest.files must be an object.');
  const findingsFile = files ? nonEmpty(files.findings) : undefined;
  const evidenceFile = files ? nonEmpty(files.evidence) : undefined;
  if (files && !findingsFile) errors.push('manifest.files.findings must name the findings file (findings.json).');
  if (files && !evidenceFile) errors.push('manifest.files.evidence must name the evidence file (evidence.md).');
  const transcript = files?.transcript;
  if (transcript !== undefined && transcript !== null && typeof transcript !== 'string') {
    errors.push('manifest.files.transcript must be a string when given.');
  }

  let orgs: InsightPacketOrg[] | undefined;
  if (version === 3) {
    if (!Array.isArray(raw.orgs)) {
      errors.push('manifest.orgs must list every org the packet queried ([] when it queried none).');
    } else {
      orgs = [];
      const seen = new Set<string>();
      raw.orgs.forEach((item, index) => {
        if (!isRecord(item)) {
          errors.push(`manifest.orgs[${index}] must be an object.`);
          return;
        }
        const alias = nonEmpty(item.alias);
        if (!alias) errors.push(`manifest.orgs[${index}].alias must be the sf alias the queries used.`);
        if (typeof item.sandbox !== 'boolean') errors.push(`manifest.orgs[${index}].sandbox must be true or false (false for production).`);
        const orgId = nonEmpty(item.orgId);
        if (item.orgId !== undefined && (!orgId || !ORG_ID.test(orgId))) errors.push(`manifest.orgs[${index}].orgId must be an org id (00D…).`);
        if (alias && !orgId) warnings.push(`manifest.orgs[${index}] (${alias}) has no orgId.`);
        if (alias && seen.has(alias)) errors.push(`manifest.orgs lists ${alias} twice.`);
        if (alias) seen.add(alias);
        if (alias && typeof item.sandbox === 'boolean') {
          orgs!.push({ alias, ...(orgId && ORG_ID.test(orgId) ? { orgId } : {}), sandbox: item.sandbox });
        }
      });
    }
  }

  if (errors.length > 0) return { errors, warnings };
  return {
    errors,
    warnings,
    manifest: {
      version: version as InsightPacketVersion,
      kind: INSIGHT_PACKET_KIND,
      createdAt: createdAt!,
      source: {
        workspaceName: workspaceName!,
        gitBranch: gitBranch ?? 'unknown',
        gitCommit: typeof gitCommit === 'string' ? gitCommit : null,
      },
      agentSession: { agent: agent as InsightAgent, toolsUsed: toolsUsed as string[] },
      goals: goals as string[],
      files: {
        findings: fileRef(findingsFile!),
        evidence: fileRef(evidenceFile!),
        ...(typeof transcript === 'string' && transcript.trim() ? { transcript: fileRef(transcript) } : {}),
      },
      ...(orgs ? { orgs } : {}),
    },
  };
}

function parseDocsCitations(value: unknown, label: string, errors: string[], warnings: string[]): InsightDocsCitation[] | undefined {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) {
    errors.push(`${label}.docsCitations must be an array when given.`);
    return undefined;
  }
  const citations: InsightDocsCitation[] = [];
  value.forEach((item, index) => {
    const url = isRecord(item) ? nonEmpty(item.url) : undefined;
    const quote = isRecord(item) ? nonEmpty(item.quote) : undefined;
    if (!url || !quote) {
      warnings.push(`${label}.docsCitations[${index}] needs the page's url and a quoted passage; without both it isn't documentation evidence.`);
      return;
    }
    const title = isRecord(item) ? nonEmpty(item.title) : undefined;
    citations.push({ url, quote, ...(title ? { title } : {}) });
  });
  return citations;
}

/**
 * A docs claim counts as grounded in the documentation only with the page's URL
 * and a quoted passage (2.9.5's grounding rule, for org agents): without both it
 * is the agent's assertion.
 */
function groundedSourceType(sourceType: InsightSourceType, citations: InsightDocsCitation[] | undefined, label: string, warnings: string[]): InsightSourceType {
  if (sourceType !== 'docs' || (citations && citations.length > 0)) return sourceType;
  warnings.push(`${label} says sourceType "docs" without a docsCitations entry (url and quote): it reads as an agent assertion.`);
  return 'agent_summary';
}

interface FindingContext {
  version: InsightPacketVersion;
  evidence: string;
  orgAliases: Set<string> | null;
  queriedOrgs: string[];
  errors: string[];
  warnings: string[];
}

function checkOrg(value: unknown, label: string, context: FindingContext): string | undefined {
  const org = nonEmpty(value);
  if (context.version !== 3) return org;
  if (!org) {
    context.errors.push(`${label}.org must name the org it ran against (an alias from manifest.orgs).`);
    return undefined;
  }
  if (context.orgAliases && !context.orgAliases.has(org)) {
    context.errors.push(`${label}.org is ${org}, which manifest.orgs doesn't list.`);
  }
  if (!context.queriedOrgs.includes(org)) context.queriedOrgs.push(org);
  return org;
}

function parseClaims(value: unknown, findingId: string, label: string, context: FindingContext): InsightEvidenceClaim[] {
  if (value === undefined) return [];
  if (!Array.isArray(value)) {
    context.errors.push(`${label}.evidenceClaims must be an array when given.`);
    return [];
  }
  const claims: InsightEvidenceClaim[] = [];
  value.forEach((item, index) => {
    const claimLabel = `${label}.evidenceClaims[${index}]`;
    if (!isRecord(item)) {
      context.errors.push(`${claimLabel} must be an object.`);
      return;
    }
    const claim = nonEmpty(item.claim);
    if (!claim) {
      context.errors.push(`${claimLabel}.claim must be a non-empty string.`);
      return;
    }
    if (!oneOf(INSIGHT_SOURCE_TYPES, item.sourceType)) {
      context.errors.push(`${claimLabel}.sourceType must be one of ${INSIGHT_SOURCE_TYPES.join(', ')}.`);
      return;
    }
    const docsCitations = parseDocsCitations(item.docsCitations, claimLabel, context.errors, context.warnings);
    const confidence = typeof item.confidence === 'number' && Number.isFinite(item.confidence)
      ? Math.max(0, Math.min(1, item.confidence))
      : undefined;
    claims.push({
      claimId: nonEmpty(item.claimId) ?? `${findingId}-claim-${index + 1}`,
      claim,
      sourceType: groundedSourceType(item.sourceType, docsCitations, claimLabel, context.warnings),
      ...(confidence !== undefined ? { confidence } : {}),
      ...(typeof item.observedAt === 'string' ? { observedAt: item.observedAt } : {}),
      evidenceRefs: isStringArray(item.evidenceRefs) ? item.evidenceRefs : [],
      queryRefs: isStringArray(item.queryRefs) ? item.queryRefs : [],
      limitations: isStringArray(item.limitations) ? item.limitations : [],
      ...(docsCitations && docsCitations.length > 0 ? { docsCitations } : {}),
    });
  });
  return claims;
}

function parseQueries(value: unknown, findingId: string, label: string, context: FindingContext): InsightRuntimeQuery[] {
  if (value === undefined) return [];
  if (!Array.isArray(value)) {
    context.errors.push(`${label}.runtimeQueries must be an array when given.`);
    return [];
  }
  const queries: InsightRuntimeQuery[] = [];
  value.forEach((item, index) => {
    const queryLabel = `${label}.runtimeQueries[${index}]`;
    if (!isRecord(item)) {
      context.errors.push(`${queryLabel} must be an object.`);
      return;
    }
    const query = nonEmpty(item.query);
    if (!query) {
      context.errors.push(`${queryLabel}.query must be a non-empty string.`);
      return;
    }
    const org = checkOrg(item.org, queryLabel, context);
    queries.push({
      id: nonEmpty(item.id) ?? `${findingId}-query-${index + 1}`,
      ...(org ? { org } : {}),
      ...(typeof item.tool === 'string' ? { tool: item.tool } : {}),
      query,
      ...(typeof item.resultShape === 'string' ? { resultShape: item.resultShape } : {}),
      ...(isRecordArray(item.rows) ? { rows: item.rows } : {}),
      ...(typeof item.rowCount === 'number' && Number.isFinite(item.rowCount) ? { rowCount: item.rowCount } : {}),
      ...(typeof item.executedAt === 'string' ? { executedAt: item.executedAt } : {}),
      ...(typeof item.observedAt === 'string' ? { observedAt: item.observedAt } : {}),
      ...(typeof item.apiVersion === 'string' ? { apiVersion: item.apiVersion } : {}),
      ...(isStringArray(item.warnings) ? { warnings: item.warnings } : {}),
    });
  });
  return queries;
}

function parseDescribes(value: unknown, findingId: string, label: string, context: FindingContext): InsightDescribeResult[] {
  if (value === undefined) return [];
  if (!Array.isArray(value)) {
    context.errors.push(`${label}.describeResults must be an array when given.`);
    return [];
  }
  const describes: InsightDescribeResult[] = [];
  value.forEach((item, index) => {
    const describeLabel = `${label}.describeResults[${index}]`;
    if (!isRecord(item)) {
      context.errors.push(`${describeLabel} must be an object.`);
      return;
    }
    const objectName = nonEmpty(item.objectName);
    if (!objectName) {
      context.errors.push(`${describeLabel}.objectName must be a non-empty string.`);
      return;
    }
    const org = checkOrg(item.org, describeLabel, context);
    describes.push({
      id: nonEmpty(item.id) ?? `${findingId}-describe-${index + 1}`,
      ...(org ? { org } : {}),
      objectName,
      ...(isRecordArray(item.fields) ? { fields: item.fields } : {}),
      ...(isStringArray(item.fieldNames) ? { fieldNames: item.fieldNames } : {}),
      ...(typeof item.apiVersion === 'string' ? { apiVersion: item.apiVersion } : {}),
      ...(typeof item.observedAt === 'string' ? { observedAt: item.observedAt } : {}),
      ...(isStringArray(item.warnings) ? { warnings: item.warnings } : {}),
    });
  });
  return describes;
}

function inferSourceType(
  explicit: InsightSourceType | undefined,
  claims: InsightEvidenceClaim[],
  queries: InsightRuntimeQuery[],
  describes: InsightDescribeResult[],
): InsightSourceType {
  if (explicit) return explicit;
  if (queries.length > 0) return 'soql';
  if (describes.length > 0) return 'describe';
  return claims.find((claim) => claim.sourceType !== 'agent_summary')?.sourceType ?? 'agent_summary';
}

export function validateInsightPacketFindings(
  content: string,
  options: { version?: InsightPacketVersion; evidence?: string; orgs?: InsightPacketOrg[] } = {},
): { findings: InsightFinding[]; queriedOrgs: string[]; errors: string[]; warnings: string[] } {
  const errors: string[] = [];
  const warnings: string[] = [];
  const raw = parseJson(content, 'findings.json', errors);
  if (!raw) return { findings: [], queriedOrgs: [], errors, warnings };
  if (!Array.isArray(raw.findings)) {
    errors.push('findings.json must contain a findings array.');
    return { findings: [], queriedOrgs: [], errors, warnings };
  }

  const version = options.version ?? CURRENT_INSIGHT_PACKET_VERSION;
  const context: FindingContext = {
    version,
    evidence: options.evidence ?? '',
    orgAliases: options.orgs ? new Set(options.orgs.map((org) => org.alias)) : null,
    queriedOrgs: [],
    errors,
    warnings,
  };
  // Before version 3 the anchor rule wasn't stated in the brief: a missing anchor warns.
  const anchorProblems = version === 3 ? errors : warnings;
  const findings: InsightFinding[] = [];
  const ids = new Set<string>();

  raw.findings.forEach((item, index) => {
    const label = `findings[${index}]`;
    if (!isRecord(item)) {
      errors.push(`${label} must be an object.`);
      return;
    }
    const before = errors.length;
    const id = nonEmpty(item.id);
    const title = nonEmpty(item.title);
    const summary = nonEmpty(item.summary);
    const recommendedNextStep = nonEmpty(item.recommendedNextStep);
    if (!id) errors.push(`${label}.id must be a non-empty string.`);
    if (!title) errors.push(`${label}.title must be a non-empty string.`);
    if (!summary) errors.push(`${label}.summary must be a non-empty string.`);
    if (!recommendedNextStep) errors.push(`${label}.recommendedNextStep must be a non-empty string.`);
    if (id && ids.has(id)) errors.push(`${label}.id ${id} is used twice.`);
    if (id) ids.add(id);
    if (!oneOf(INSIGHT_SEVERITIES, item.severity)) errors.push(`${label}.severity must be critical, high, medium or low.`);
    if (!oneOf(INSIGHT_AUDIENCES, item.audienceImpact)) errors.push(`${label}.audienceImpact must be executive, product, engineering, security or operations.`);
    if (!isStringArray(item.affectedPaths)) errors.push(`${label}.affectedPaths must be an array of strings.`);
    if (!isStringArray(item.affectedComponents)) errors.push(`${label}.affectedComponents must be an array of strings.`);
    if (!isStringArray(item.evidenceRefs)) {
      errors.push(`${label}.evidenceRefs must be an array of strings.`);
    } else {
      if (item.evidenceRefs.length === 0) anchorProblems.push(`${label}.evidenceRefs is empty: point at its section in evidence.md (evidence.md#<anchor>).`);
      for (const ref of item.evidenceRefs) {
        const anchor = anchorOf(ref);
        if (!anchor || !hasAnchor(context.evidence, anchor)) {
          anchorProblems.push(`${label}.evidenceRefs has ${ref}, but evidence.md has no id="${anchor ?? ''}" or heading with that anchor.`);
        }
      }
    }
    if (item.documentationRefs !== undefined && !isStringArray(item.documentationRefs)) errors.push(`${label}.documentationRefs must be an array of strings when given.`);
    if (item.sourceType !== undefined && !oneOf(INSIGHT_SOURCE_TYPES, item.sourceType)) {
      errors.push(`${label}.sourceType must be one of ${INSIGHT_SOURCE_TYPES.join(', ')} when given.`);
    }
    if (item.observedAt !== undefined && typeof item.observedAt !== 'string') errors.push(`${label}.observedAt must be a string when given.`);
    const confidence = item.confidence;
    if (typeof confidence !== 'number' || Number.isNaN(confidence) || confidence < 0 || confidence > 1) {
      errors.push(`${label}.confidence must be a number from 0 to 1.`);
    }
    const findingId = id ?? `finding-${index + 1}`;
    const claims = parseClaims(item.evidenceClaims, findingId, label, context);
    const queries = parseQueries(item.runtimeQueries, findingId, label, context);
    const describes = parseDescribes(item.describeResults, findingId, label, context);
    const docsCitations = parseDocsCitations(item.docsCitations, label, errors, warnings);
    if (errors.length > before) return;

    const explicit = oneOf(INSIGHT_SOURCE_TYPES, item.sourceType) ? item.sourceType : undefined;
    const sourceType = groundedSourceType(inferSourceType(explicit, claims, queries, describes), docsCitations, label, warnings);
    findings.push({
      id: id!,
      title: title!,
      severity: item.severity as InsightSeverity,
      audienceImpact: item.audienceImpact as InsightAudience,
      summary: summary!,
      affectedPaths: item.affectedPaths as string[],
      affectedComponents: item.affectedComponents as string[],
      evidenceRefs: item.evidenceRefs as string[],
      recommendedNextStep: recommendedNextStep!,
      confidence: confidence as number,
      sourceType,
      ...(typeof item.observedAt === 'string' ? { observedAt: item.observedAt } : {}),
      ...(claims.length > 0 ? { evidenceClaims: claims } : {}),
      ...(queries.length > 0 ? { runtimeQueries: queries } : {}),
      ...(describes.length > 0 ? { describeResults: describes } : {}),
      ...(isStringArray(item.documentationRefs) ? { documentationRefs: item.documentationRefs } : {}),
      ...(docsCitations && docsCitations.length > 0 ? { docsCitations } : {}),
    });
  });

  return { findings, queriedOrgs: context.queriedOrgs, errors, warnings };
}

/** The limits readings file: `limit,max,remaining,at`, one row per limit per reading. */
export function validateInsightLimitsCsv(content: string): { errors: string[]; rows: number } {
  const lines = content.split(/\r?\n/).filter((line) => line.trim());
  const header = (lines[0] ?? '').split(',').map((cell) => cell.trim().toLowerCase());
  const errors: string[] = [];
  for (const column of ['limit', 'max', 'remaining', 'at']) {
    if (!header.includes(column)) errors.push(`limits.csv needs a ${column} column (header: limit,max,remaining,at).`);
  }
  return { errors, rows: Math.max(0, lines.length - 1) };
}

/** drift.json: `{ "version": 1, "org": "<alias>", "retrievedAt": "<ISO>", "components": [{ "type", "name", "status", "repoPath"?, "orgPath"? }] }`. */
export function validateInsightDriftJson(content: string, orgs?: InsightPacketOrg[]): { errors: string[]; components: number } {
  const errors: string[] = [];
  const raw = parseJson(content, 'drift.json', errors);
  if (!raw) return { errors, components: 0 };
  if (raw.version !== 1) errors.push('drift.json version must be 1.');
  const org = nonEmpty(raw.org);
  if (!org) errors.push('drift.json org must name the org retrieved from (its alias).');
  else if (orgs && !orgs.some((item) => item.alias === org)) errors.push(`drift.json org is ${org}, which manifest.orgs doesn't list.`);
  const retrievedAt = nonEmpty(raw.retrievedAt);
  if (!retrievedAt || Number.isNaN(Date.parse(retrievedAt))) errors.push('drift.json retrievedAt must be an ISO-8601 timestamp.');
  if (!Array.isArray(raw.components)) {
    errors.push('drift.json components must be an array.');
    return { errors, components: 0 };
  }
  raw.components.forEach((item, index) => {
    const label = `drift.json components[${index}]`;
    if (!isRecord(item) || !nonEmpty(item.type) || !nonEmpty(item.name)) {
      errors.push(`${label} needs a metadata type and a name.`);
    } else if (!oneOf(INSIGHT_DRIFT_STATUSES, item.status)) {
      errors.push(`${label}.status must be ${INSIGHT_DRIFT_STATUSES.join(', ')}.`);
    }
  });
  return { errors, components: raw.components.length };
}

/**
 * One packet, every rule: the manifest, the files it names, the findings (their
 * anchors in evidence.md, and in version 3 the org each query ran against), and
 * limits.csv and drift.json when there are.
 */
export function validateInsightPacket(files: InsightPacketFileContents): InsightPacketValidation {
  const byName = new Map<string, string | undefined>();
  for (const [name, content] of Object.entries(files)) byName.set(fileRef(name).toLowerCase(), content);
  const empty = (errors: string[], warnings: string[] = []): InsightPacketValidation => ({
    status: 'invalid', errors, warnings, findings: [], queriedOrgs: [], productionOrgs: [], orgRecorded: false,
  });

  const manifestContent = byName.get('manifest.json');
  if (manifestContent === undefined) {
    return empty(['manifest.json is missing (the agent writes it last, so the packet may still be being written).']);
  }
  const manifestResult = validateInsightPacketManifest(manifestContent);
  const warnings = [...manifestResult.warnings];
  if (!manifestResult.manifest) return empty(manifestResult.errors, warnings);
  const manifest = manifestResult.manifest;

  const errors: string[] = [];
  const findingsContent = byName.get(manifest.files.findings.toLowerCase());
  const evidenceContent = byName.get(manifest.files.evidence.toLowerCase());
  if (findingsContent === undefined) errors.push(`${manifest.files.findings} is missing.`);
  if (evidenceContent === undefined) errors.push(`${manifest.files.evidence} is missing.`);
  if (manifest.files.transcript && byName.get(manifest.files.transcript.toLowerCase()) === undefined) {
    warnings.push(`The manifest names ${manifest.files.transcript}, which isn't in the packet.`);
  }
  if (errors.length > 0) return { ...empty(errors, warnings), manifest };

  const findingsResult = validateInsightPacketFindings(findingsContent!, {
    version: manifest.version,
    evidence: evidenceContent,
    orgs: manifest.orgs,
  });
  errors.push(...findingsResult.errors);
  warnings.push(...findingsResult.warnings);

  const limits = byName.get('limits.csv');
  if (limits !== undefined) errors.push(...validateInsightLimitsCsv(limits).errors);
  const drift = byName.get('drift.json');
  if (drift !== undefined) errors.push(...validateInsightDriftJson(drift, manifest.orgs).errors);

  const orgRecorded = manifest.version === 3;
  if (!orgRecorded) warnings.push(`Which org this packet queried isn't recorded (manifest version ${manifest.version}).`);
  if (orgRecorded) {
    for (const org of manifest.orgs ?? []) {
      if (!findingsResult.queriedOrgs.includes(org.alias)) warnings.push(`manifest.orgs lists ${org.alias}, but no query or describe ran against it.`);
    }
  }

  return {
    status: errors.length > 0 ? 'invalid' : 'valid',
    errors,
    warnings,
    manifest,
    findings: errors.length > 0 ? [] : findingsResult.findings,
    queriedOrgs: findingsResult.queriedOrgs,
    productionOrgs: (manifest.orgs ?? []).filter((org) => !org.sandbox),
    orgRecorded,
  };
}
